True def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                points[value] = (r, c)
    r, c = points[1]
    target_r, target_c = points[2]
    dr = (target_r > r) - (target_r < r)
    dc = (target_c > c) - (target_c < c)
    nr, nc = abs(target_r - r), abs(target_c - c)
    diagonal_steps = max(0, min(nr, nc) - 1)
    for _ in range(diagonal_steps):
        r += dr
        c += dc
        out[r][c] = 3
    if nr > nc:
        for _ in range(nr - nc):
            r += dr
            out[r][c] = 3
    elif nc > nr:
        for _ in range(nc - nr):
            c += dc
            out[r][c] = 3
    return out
